#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<string> exp = {"2", "3", "4", "*", "+"};
    stack<int> st;
    for (string x : exp) {
        if (isdigit(x[0])) st.push(stoi(x));
        else {
            int b = st.top(); st.pop();
            int a = st.top(); st.pop();
            if (x == "+") st.push(a + b);
            if (x == "*") st.push(a * b);
        }
    }
    cout << st.top() << endl; // 14
}
